// 回复在原受信人明确领读后由其本人选择；原发信人仍须到接待点真实领回，不能远程读心。
#include "visit_reply_detail.hpp"
#include "visit_reply_life.hpp"
#include <set>
namespace hanmo::resident {namespace {
template<class T>Outcome<T> fail(const StableId& code){return {false,{},common_failure(code).error};}
}
StableId visit_reply_command_kind(const VisitReplyCommand& c){return std::holds_alternative<ReplyVisitMessage>(c)?"reply_visit_message":"collect_visit_message_reply";}
BoundaryValue encode_visit_reply_command(const VisitReplyCommand& c){using V=BoundaryValue;if(const auto* p=std::get_if<ReplyVisitMessage>(&c))return boundary::obj({{"policy_id",V{p->policy_id}},{"message_fact_id",V{p->message_fact_id}},{"response",V{p->response}}});return boundary::obj({{"reply_fact_id",V{std::get<CollectVisitMessageReply>(c).reply_fact_id}}});}
Outcome<VisitReplyCommand> decode_visit_reply_command(const StableId& kind,const BoundaryValue& value){try{using namespace boundary;std::set<StableId> keys;for(const auto& f:object(value,kind))if(!keys.insert(f.first).second)fail("DuplicateVisitReplyField",f.first);const auto id=[&](const char* key){auto v=get_string(value,key,kind);if(v.empty()||v.size()>256)fail("InvalidVisitReplyCommand",key);return v;};if(kind=="reply_visit_message"){fields(value,{"policy_id","message_fact_id","response"},{},kind);auto response=id("response");if(response!="declined"&&response!="contact_in_person")fail("UnsupportedVisitReplyResponse","response");return {true,ReplyVisitMessage{id("policy_id"),id("message_fact_id"),std::move(response)},{}};}if(kind!="collect_visit_message_reply")unsupported("UnsupportedVisitReplyCommand",kind);fields(value,{"reply_fact_id"},{},kind);return {true,CollectVisitMessageReply{id("reply_fact_id")},{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<VisitReplyQuote> preview_visit_reply(const CommonStore& common,const VisitMessageState& messages,const VisitMessageCatalog& originals,const InteractionState& interaction,const InteractionCatalog& definitions,const InteractionAccess& access,const VisitReplyCatalog& catalog,const VisitReplyState& state,const StableId& actor,const VisitReplyCommand& command,const VisitReplyLifeContext*life){
    std::optional<WorldMoment> actual;if(visit_reply_life_version(state.version)){if(!life)return {false,{},common_failure("VisitReplyLife4SourcesRequired",{},ErrorKind::unsupported_capability).error};if(&life->messages.common!=&common||&life->messages.state!=&messages||&life->messages.policies!=&originals||&life->messages.interactions!=&interaction||&life->messages.interaction!=&definitions||&life->state!=&state||&life->policies!=&catalog)return {false,{},common_failure("VisitReplyLifeCandidateMismatch",{},ErrorKind::internal).error};auto now=life->messages.clock.read_current_moment();if(!now.ok)return {false,{},now.error};actual=std::move(now.value);}else if(life)return fail<VisitReplyQuote>("UnselectedVisitReplyLifeSources");const Integer actual_tick=actual?actual->half_day_tick:common.tick();
    auto valid=validate_visit_message_catalog(originals,definitions);if(!valid.ok)return {false,{},valid.error};valid=validate_visit_reply_catalog(catalog,originals,definitions);if(!valid.ok)return {false,{},valid.error};if(!visit_reply_version(state.version)||state.version!=catalog.version)return fail<VisitReplyQuote>("UnsupportedVisitReplyVersion");
    const bool posting=std::holds_alternative<ReplyVisitMessage>(command);const VisitReplyPosted* reply=nullptr;const VisitMessagePosted* message=nullptr;const VisitReplyPolicy* policy=nullptr;
    if(posting){const auto& c=std::get<ReplyVisitMessage>(command);policy=visit_reply_detail::policy(catalog,c.policy_id);message=messages.posted.find(c.message_fact_id);if(c.response!="declined"&&c.response!="contact_in_person")return fail<VisitReplyQuote>("UnsupportedVisitReplyResponse");}
    else{reply=state.posted.find(std::get<CollectVisitMessageReply>(command).reply_fact_id);if(reply){policy=visit_reply_detail::policy(catalog,reply->policy_id);message=messages.posted.find(reply->message_fact_id);}}
    const auto* p=policy?visit_reply_detail::original(originals,policy->message_policy_id):nullptr;
    if(!p||!message||message->policy_id!=p->id||actor!=(posting?p->recipient_actor_id:p->sender_actor_id))return fail<VisitReplyQuote>("VisitReplyNotKnown");
    // 在公开状态/内容之前先核本人真实会面，未知ID与不在原现场同码，不泄露远方回复。
    auto proof=preview_authored_provider_source(common,interaction,definitions,access,actor,p->custodian_actor_id);if(!proof.ok)return fail<VisitReplyQuote>("VisitReplyNotKnown");const auto& m=proof.value.meeting;const auto* role=definitions.common->roles.find(p->role_id);if(!role||m.context.role_id!=p->role_id||m.context.place_id!=role->place_id||m.dialogue_id!=p->dialogue_id||m.node_id!=(posting?policy->reply_node_id:policy->collect_node_id)||m.context.kind||m.context.encounter_id||m.context.input_error)return fail<VisitReplyQuote>("VisitReplyNotKnown");
    if(life){for(const auto&person:{actor,p->custodian_actor_id}){auto present=life->people.read_current_presence(person);if(!present.ok)return {false,{},present.error};if(!present.value.alive)return fail<VisitReplyQuote>("VisitReplyNotKnown");}valid=validate_visit_reply_life_command(*life,command);if(!valid.ok)return {false,{},valid.error};}
    const auto* received=visit_reply_detail::received(messages,message->fact_id);if(!received||received->contact.actor_id!=p->recipient_actor_id||received->contact.tick>actual_tick)return fail<VisitReplyQuote>("VisitReplyOriginalDeliveryRequired");
    if(posting){if(visit_reply_detail::replied(state,message->fact_id))return fail<VisitReplyQuote>("VisitReplyAlreadyPosted");if(state.posted.size()>=65536)return fail<VisitReplyQuote>("VisitReplyHistoryLimit");}
    else{if(reply->received_fact_id!=received->fact_id||reply->contact.tick>actual_tick)return fail<VisitReplyQuote>("VisitReplyOriginalDeliveryRequired");if(visit_reply_detail::collected(state,reply->fact_id))return fail<VisitReplyQuote>("VisitReplyAlreadyCollected");if(state.collected.size()>=65536)return fail<VisitReplyQuote>("VisitReplyHistoryLimit");}
    return {true,{std::move(proof.value),command,policy->id,message->fact_id,received->fact_id,reply?reply->fact_id:StableId{},std::move(actual)},{}};
}
Outcome<StableId> apply_visit_reply_in_candidate(CommonStore& common,const VisitMessageState& messages,const VisitMessageCatalog& originals,const InteractionState& interaction,const InteractionCatalog& definitions,const InteractionAccess& access,const VisitReplyCatalog& catalog,VisitReplyState& state,const StableId& actor,const VisitReplyCommand& command,const VisitReplyQuote& quote,const VisitReplyLifeContext*life){
    if(actor!=quote.source.meeting.actor_id||visit_reply_command_kind(command)!=visit_reply_command_kind(quote.command)||!compare_boundary(encode_visit_reply_command(command),encode_visit_reply_command(quote.command)).exact())return fail<StableId>("StaleVisitReplyQuote");auto valid=revalidate_authored_provider_source(common,interaction,definitions,access,quote.source);if(!valid.ok)return {false,{},valid.error};auto fresh=preview_visit_reply(common,messages,originals,interaction,definitions,access,catalog,state,actor,command,life);if(!fresh.ok)return {false,{},fresh.error};const auto& q=fresh.value;if(bool(q.actual_quoted_at)!=bool(quote.actual_quoted_at))return fail<StableId>("StaleVisitReplyQuote");if(q.actual_quoted_at){auto time=compare_world_moments(*q.actual_quoted_at,*quote.actual_quoted_at);if(!time.ok)return {false,{},time.error};if(time.value!=0)return fail<StableId>("StaleVisitReplyQuote");}if(q.policy_id!=quote.policy_id||q.message_fact_id!=quote.message_fact_id||q.received_fact_id!=quote.received_fact_id||q.reply_fact_id!=quote.reply_fact_id)return fail<StableId>("StaleVisitReplyQuote");
    const bool posting=std::holds_alternative<ReplyVisitMessage>(command);const StableId kind=posting?visit_reply_posted_kind:visit_reply_collected_kind;auto id=common.next_id(kind);if(!id.ok)return id;valid=common.append_fact({id.value,kind,visit_reply_module});if(!valid.ok)return {false,{},valid.error};const auto contact=visit_reply_detail::contact(q.source,q.actual_quoted_at?q.actual_quoted_at->half_day_tick:common.tick());bool inserted=false;if(posting)inserted=state.posted.insert(id.value,{id.value,q.policy_id,q.message_fact_id,q.received_fact_id,std::get<ReplyVisitMessage>(command).response,contact});else inserted=state.collected.insert(id.value,{id.value,q.reply_fact_id,contact});if(!inserted)return fail<StableId>("DuplicateVisitReplyFact");rebuild_visit_reply_indexes(state);return id;
}
}
